#!/usr/bin/env node
/**
 * test-all.js
 *
 * Single entry point for the local gate. package.json is generated by
 * scripts/build-agent-dist.js, so the `test:gates` script lives in the
 * template there — and its value used to be one enormous `&&` chain naming
 * 6 validators, an eval run and 8 test files. That list existed in three
 * places (the package.json value, the template, and the CI workflow) and
 * nothing compared them, so they drifted. Collapsing it to this one script
 * removes two of the three copies, makes `npm test` a single command a
 * contributor can run on any OS, and stops the chain depending on
 * shell-specific `&&` semantics.
 *
 * Runs each step in order with spawnSync (stdio: 'inherit') from the repo
 * root and STOPS at the first non-zero status — it prints which step failed
 * and exits with that step's code, so a failure is never swallowed by
 * continuing. Test files run as `node <file>` (a plain node invocation),
 * not `node --test <files>`: node:test files set a non-zero exit code when
 * executed directly, and the plain form is what this repo's harness accepts.
 *
 * Exit codes:
 *   0 - all steps passed
 *   N - the first failing step's exit code (non-zero)
 *
 * Uses built-in Node.js modules only. Zero external dependencies.
 */

'use strict';

const { spawnSync } = require('child_process');
const path = require('path');

const STEPS = [
  { label: 'validate-skills', argv: ['scripts/validate-skills.js'] },
  { label: 'validate-versions', argv: ['scripts/validate-versions.js'] },
  { label: 'validate-reference-links', argv: ['scripts/validate-reference-links.js'] },
  { label: 'validate-commands', argv: ['scripts/validate-commands.js'] },
  { label: 'validate-artifact-paths', argv: ['scripts/validate-artifact-paths.js'] },
  { label: 'validate-catalog', argv: ['scripts/validate-catalog.js'] },
  { label: 'run-evals', argv: ['scripts/run-evals.js', '--min-rank1', '95'] },
  { label: 'skill-lint-test', argv: ['scripts/lib/skill-lint-test.js'] },
  { label: 'validate-versions-test', argv: ['scripts/validate-versions-test.js'] },
  { label: 'run-evals-test', argv: ['scripts/run-evals-test.js'] },
  { label: 'validate-reference-links-test', argv: ['scripts/validate-reference-links-test.js'] },
  { label: 'validate-commands-test', argv: ['scripts/validate-commands-test.js'] },
  { label: 'validate-artifact-paths-test', argv: ['scripts/validate-artifact-paths-test.js'] },
  { label: 'floor-guard-reference-test', argv: ['scripts/floor-guard-reference-test.js'] },
  { label: 'validate-catalog-test', argv: ['scripts/validate-catalog-test.js'] },
  { label: 'uninstall-test', argv: ['scripts/uninstall-test.js'] },
];

function main() {
  const repoRoot = path.resolve(__dirname, '..');
  let passed = 0;
  for (const step of STEPS) {
    console.log(`\n[${passed + 1}/${STEPS.length}] ${step.label}`);
    const result = spawnSync(process.execPath, step.argv, {
      cwd: repoRoot,
      stdio: 'inherit',
    });
    if (result.error) {
      console.error(`\nFailed to execute step "${step.label}": ${result.error.message}`);
      process.exit(1);
    }
    if (result.status !== 0) {
      console.error(`\nStep failed: ${step.label} (exit code ${result.status == null ? 1 : result.status})`);
      process.exit(result.status == null ? 1 : result.status);
    }
    passed += 1;
  }
  console.log(`\nAll ${passed}/${STEPS.length} steps passed.`);
  process.exit(0);
}

if (require.main === module) {
  main();
}

module.exports = { STEPS };
